    assertEquals(0, hdfsInputStream.getPos());
    assertEquals(lenOfBytes, hdfsInputStream.length());
    hdfsInputStream.seek(10);
    assertEquals(10, hdfsInputStream.getPos());
    hdfsInputStream.seek(0);
