@Test
public void RecordReaderTest() {
    TsFileTestHelper.writeTsFile(tsfilePath);
    try {
        Job job = Job.getInstance();
        // set input path to the job
        TSFInputFormat.setInputPaths(job, tsfilePath);
        String[] devices = { "root.car.d1" };
        TSFInputFormat.setReadDeltaObjectIds(job, devices);
        String[] sensors = { "s1", "s2", "s3", "s4", "s5", "s6" };
        TSFInputFormat.setReadMeasurementIds(job, sensors);
        TSFInputFormat.setReadDeltaObjectId(job, false);
        TSFInputFormat.setReadTime(job, false);
        List<InputSplit> inputSplits = inputformat.getSplits(job);
        ITsRandomAccessFileReader reader = new TsRandomAccessLocalFileReader(tsfilePath);
        TsFile tsFile = new TsFile(reader);
        System.out.println(tsFile.getDeltaObjectRowGroupCount());
        //assertEquals(tsFile.getRowGroupPosList().size(), inputSplits.size());
        for (InputSplit inputSplit : inputSplits) {
            System.out.println(inputSplit);
        }
        reader.close();
        // read one split
        TSFRecordReader recordReader = new TSFRecordReader();
        TaskAttemptContextImpl attemptContextImpl = new TaskAttemptContextImpl(job.getConfiguration(), new TaskAttemptID());
        recordReader.initialize(inputSplits.get(0), attemptContextImpl);
        while (recordReader.nextKeyValue()) {
            assertEquals(recordReader.getCurrentValue().get().length, sensors.length);
            for (Writable writable : recordReader.getCurrentValue().get()) {
                if (writable instanceof IntWritable) {
                    assertEquals(writable.toString(), "1");
                } else if (writable instanceof LongWritable) {
                    assertEquals(writable.toString(), "1");
                } else if (writable instanceof FloatWritable) {
                    assertEquals(writable.toString(), "0.1");
                } else if (writable instanceof DoubleWritable) {
                    assertEquals(writable.toString(), "0.1");
                } else if (writable instanceof BooleanWritable) {
                    assertEquals(writable.toString(), "true");
                } else if (writable instanceof Text) {
                    assertEquals(writable.toString(), "tsfile");
                } else {
                    fail(String.format("Not support type %s", writable.getClass().getName()));
                }
            }
        }
        recordReader.close();
    } catch (IOException e) {
        e.printStackTrace();
        fail(e.getMessage());
    } catch (InterruptedException e) {
        e.printStackTrace();
        fail(e.getMessage());
    } catch (TSFHadoopException e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
}

@Test
public void testInputSplitWriteAndRead() {
    try {
        // call the write method to serialize the object
        wInputSplit.write(DataOutputBuffer);
        DataOutputBuffer.flush();
        DataInputBuffer.reset(DataOutputBuffer.getData(), DataOutputBuffer.getLength());
        rInputSplit.readFields(DataInputBuffer);
        DataInputBuffer.close();
        DataOutputBuffer.close();
        // assert
        assertEquals(wInputSplit.getPath(), rInputSplit.getPath());
        assertEquals(wInputSplit.getNumOfDeviceRowGroup(), rInputSplit.getNumOfDeviceRowGroup());
        //assertEquals(wInputSplit.getDeviceRowGroupMetaDataList(), rInputSplit.getDeviceRowGroupMetaDataList());
        assertEquals(wInputSplit.getStart(), rInputSplit.getStart());
        try {
            assertEquals(wInputSplit.getLength(), rInputSplit.getLength());
            assertArrayEquals(wInputSplit.getLocations(), rInputSplit.getLocations());
        } catch (InterruptedException e) {
            e.printStackTrace();
            fail(e.getMessage());
        }
    } catch (IOException e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
}

@Test
public void testAuthorizer() throws AuthException {
    IAuthorizer authorizer = LocalFileAuthorizer.getInstance();
    /*
     * login
     */
    boolean status = false;
    try {
        status = authorizer.login("root", "root");
        assertEquals(true, status);
    } catch (AuthException e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
    try {
        status = authorizer.login("root", "error");
    } catch (AuthException e) {
        assertEquals("The username or the password is not correct", e.getMessage());
    }
    /*
     * create user,delete user
     */
    User user = new User("user", "password");
    try {
        status = authorizer.createUser(user.getName(), user.getPassword());
        assertEquals(true, status);
    } catch (AuthException e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
    try {
        status = authorizer.createUser(user.getName(), user.getPassword());
    } catch (AuthException e) {
        assertEquals("The user is exist", e.getMessage());
    }
    try {
        status = authorizer.login(user.getName(), user.getPassword());
        assertEquals(true, status);
    } catch (AuthException e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
    try {
        status = authorizer.deleteUser(user.getName());
        assertEquals(true, status);
    } catch (AuthException e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
    try {
        status = authorizer.deleteUser(user.getName());
    } catch (AuthException e) {
        assertEquals("The user is not exist", e.getMessage());
    }
    /*
     * permission for user
     */
    String nodeName = "root.laptop.d1";
    try {
        authorizer.createUser(user.getName(), user.getPassword());
        status = authorizer.grantPrivilegeToUser(user.getName(), nodeName, 1);
        assertEquals(true, status);
    } catch (AuthException e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
    try {
        authorizer.grantPrivilegeToUser(user.getName(), nodeName, 1);
    } catch (AuthException e) {
        assertEquals("The permission is exist", e.getMessage());
    }
    try {
        authorizer.grantPrivilegeToUser("error", nodeName, 1);
    } catch (AuthException e) {
        assertEquals("No such user error", e.getMessage());
    }
    try {
        status = authorizer.revokePrivilegeFromUser(user.getName(), nodeName, 1);
        assertEquals(true, status);
    } catch (AuthException e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
    try {
        status = authorizer.revokePrivilegeFromUser(user.getName(), nodeName, 1);
    } catch (AuthException e) {
        assertEquals("The permission is not exist", e.getMessage());
    }
    try {
        authorizer.deleteUser(user.getName());
        authorizer.revokePrivilegeFromUser(user.getName(), nodeName, 1);
    } catch (AuthException e) {
        assertEquals("No such user user", e.getMessage());
    }
    /*
     * role
     */
    String roleName = "role";
    try {
        status = authorizer.createRole(roleName);
        assertEquals(true, status);
    } catch (AuthException e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
    try {
        status = authorizer.createRole(roleName);
    } catch (AuthException e) {
        assertEquals("The role is exist", e.getMessage());
    }
    try {
        status = authorizer.deleteRole(roleName);
        assertEquals(true, status);
    } catch (AuthException e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
    try {
        status = authorizer.deleteRole(roleName);
    } catch (AuthException e) {
        assertEquals("The role is not exist", e.getMessage());
    }
    /*
     * role permission
     */
    try {
        status = authorizer.createRole(roleName);
        status = authorizer.grantPrivilegeToRole(roleName, nodeName, 1);
        assertEquals(true, status);
    } catch (AuthException e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
    try {
        status = authorizer.grantPrivilegeToRole(roleName, nodeName, 1);
    } catch (AuthException e) {
        assertEquals("The permission is exist", e.getMessage());
    }
    try {
        status = authorizer.revokePrivilegeFromRole(roleName, nodeName, 1);
        assertEquals(true, status);
    } catch (AuthException e1) {
        fail(e1.getMessage());
    }
    try {
        authorizer.revokePrivilegeFromRole(roleName, nodeName, 1);
    } catch (AuthException e) {
        assertEquals("The permission is not exist", e.getMessage());
    }
    try {
        authorizer.deleteRole(roleName);
    } catch (AuthException e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
    try {
        authorizer.revokePrivilegeFromRole(roleName, nodeName, 1);
    } catch (AuthException e) {
        assertEquals("No such role role", e.getMessage());
    }
    try {
        authorizer.grantPrivilegeToRole(roleName, nodeName, 1);
    } catch (AuthException e) {
        assertEquals("No such role role", e.getMessage());
    }
    /*
     * user role
     */
    try {
        authorizer.createUser(user.getName(), user.getPassword());
        authorizer.createRole(roleName);
        status = authorizer.grantRoleToUser(roleName, user.getName());
        assertEquals(true, status);
    } catch (AuthException e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
    try {
        authorizer.grantPrivilegeToUser(user.getName(), nodeName, 1);
        authorizer.grantPrivilegeToRole(roleName, nodeName, 2);
        authorizer.grantPrivilegeToRole(roleName, nodeName, 3);
    } catch (AuthException e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
    try {
        Set<Integer> permisssions = authorizer.getPrivileges(user.getName(), nodeName);
        assertEquals(3, permisssions.size());
        assertEquals(true, permisssions.contains(1));
        assertEquals(true, permisssions.contains(2));
        assertEquals(true, permisssions.contains(3));
        assertEquals(false, permisssions.contains(4));
    } catch (AuthException e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
    try {
        status = authorizer.revokeRoleFromUser(roleName, user.getName());
        assertEquals(true, status);
        Set<Integer> permisssions = authorizer.getPrivileges(user.getName(), nodeName);
        assertEquals(1, permisssions.size());
        assertEquals(true, permisssions.contains(1));
        assertEquals(false, permisssions.contains(2));
    } catch (AuthException e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
    try {
        status = authorizer.checkUserPrivileges(user.getName(), nodeName, 1);
    } catch (AuthException e) {
        fail(e.getMessage());
    }
    assertEquals(true, status);
    try {
        status = authorizer.checkUserPrivileges(user.getName(), nodeName, 2);
    } catch (AuthException e) {
        fail(e.getMessage());
    }
    assertEquals(false, status);
    try {
        status = authorizer.updateUserPassword(user.getName(), "newPassword");
        assertEquals(true, status);
        status = authorizer.login(user.getName(), "newPassword");
        assertEquals(true, status);
    } catch (AuthException e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
    try {
        authorizer.deleteUser(user.getName());
        authorizer.deleteRole(roleName);
    } catch (AuthException e) {
        e.printStackTrace();
    }
}

@Test
public void testListUser() throws AuthException {
    IAuthorizer authorizer = LocalFileAuthorizer.getInstance();
    List<String> userList = authorizer.listAllUsers();
    assertEquals(1, userList.size());
    assertEquals(IoTDBConstant.ADMIN_NAME, userList.get(0));
    int userCnt = 10;
    for (int i = 0; i < userCnt; i++) {
        authorizer.createUser("newUser" + i, "password" + i);
    }
    userList = authorizer.listAllUsers();
    assertEquals(11, userList.size());
    for (int i = 0; i < userCnt; i++) {
        assertEquals("newUser" + i, userList.get(i));
    }
    for (int i = 0; i < userCnt; i++) {
        if (i % 2 == 0) {
            authorizer.deleteUser("newUser" + i);
        }
    }
    userList = authorizer.listAllUsers();
    assertEquals(6, userList.size());
    for (int i = 0; i < userCnt; i++) {
        if (i % 2 == 1) {
            assertEquals("newUser" + i, userList.get(i / 2));
        }
    }
}

@Test
public void testListRole() throws AuthException {
