    QueryContext context = new QueryContext();
    // write update data
    OverflowSeriesDataSource overflowSeriesDataSource = processor.query(OverflowTestUtils.deviceId1, OverflowTestUtils.measurementId1, OverflowTestUtils.dataType1, Collections.emptyMap(), context);
    assertEquals(OverflowTestUtils.dataType1, overflowSeriesDataSource.getDataType());
    Assert.assertEquals(true, overflowSeriesDataSource.getReadableMemChunk().isEmpty());
    assertEquals(1, overflowSeriesDataSource.getOverflowInsertFileList().size());
    assertEquals(0, overflowSeriesDataSource.getOverflowInsertFileList().get(0).getChunkMetaDataList().size());
    processor.flush();
    assertEquals(false, processor.isMerge());
    // write insert data
    OverflowTestUtils.produceInsertData(processor);
    TimeUnit.SECONDS.sleep(1);
    assertEquals(false, processor.isFlush());
    overflowSeriesDataSource = processor.query(OverflowTestUtils.deviceId1, OverflowTestUtils.measurementId1, OverflowTestUtils.dataType1, Collections.emptyMap(), context);
    assertEquals(OverflowTestUtils.dataType1, overflowSeriesDataSource.getDataType());
    Assert.assertEquals(false, overflowSeriesDataSource.getReadableMemChunk().isEmpty());
    assertEquals(1, overflowSeriesDataSource.getOverflowInsertFileList().size());
    Iterator<TimeValuePair> iterator = overflowSeriesDataSource.getReadableMemChunk().getIterator();
    for (int i = 1; i <= 3; i++) {
        assertEquals(true, iterator.hasNext());
        TimeValuePair pair = iterator.next();
        assertEquals(i, pair.getTimestamp());
        assertEquals(i, pair.getValue().getInt());
    }
    // flush synchronously
    processor.close();
    processor.reopen();
    overflowSeriesDataSource = processor.query(OverflowTestUtils.deviceId1, OverflowTestUtils.measurementId1, OverflowTestUtils.dataType1, Collections.emptyMap(), context);
    Assert.assertEquals(true, overflowSeriesDataSource.getReadableMemChunk().isEmpty());
    assertEquals(1, overflowSeriesDataSource.getOverflowInsertFileList().size());
    assertEquals(1, overflowSeriesDataSource.getOverflowInsertFileList().get(0).getChunkMetaDataList().size());
    processor.switchWorkToMerge();
    overflowSeriesDataSource = processor.query(OverflowTestUtils.deviceId1, OverflowTestUtils.measurementId1, OverflowTestUtils.dataType1, Collections.emptyMap(), context);
    assertEquals(2, overflowSeriesDataSource.getOverflowInsertFileList().size());
    assertEquals(1, overflowSeriesDataSource.getOverflowInsertFileList().get(0).getChunkMetaDataList().size());
    assertEquals(0, overflowSeriesDataSource.getOverflowInsertFileList().get(1).getChunkMetaDataList().size());
    assertEquals(true, processor.isMerge());
    assertEquals(false, processor.canBeClosed());
    MergeSeriesDataSource mergeSeriesDataSource = processor.queryMerge(OverflowTestUtils.deviceId1, OverflowTestUtils.measurementId1, OverflowTestUtils.dataType1, context);
    assertEquals(1, mergeSeriesDataSource.getInsertFile().getChunkMetaDataList().size());
    processor.switchMergeToWork();
    overflowSeriesDataSource = processor.query(OverflowTestUtils.deviceId1, OverflowTestUtils.measurementId1, OverflowTestUtils.dataType1, Collections.emptyMap(), context);
    processor.close();
    processor.clear();
}

