@Test
public void showTimeseriesTest1() throws ClassNotFoundException, SQLException {
    Class.forName(Config.JDBC_DRIVER_NAME);
    Connection connection = null;
    try {
        connection = DriverManager.getConnection(Config.IOTDB_URL_PREFIX + "127.0.0.1:6667/", "root", "root");
        Statement statement = connection.createStatement();
        String[] sqls = new String[] { // full seriesPath
        "show timeseries root.ln.wf01.wt01.status", // prefix seriesPath
        "show timeseries root.ln", // seriesPath with stars
        "show timeseries root.ln.*.wt01", // nonexistent timeseries, thus returning ""
        "show timeseries root.a.b", "show timeseries root.ln,root.ln" // SHOW TIMESERIES <PATH> only accept single seriesPath, thus
        // returning ""
        };
        String[] standards = new String[] { "root.ln.wf01.wt01.status,root.ln.wf01.wt01,BOOLEAN,PLAIN,\n", "root.ln.wf01.wt01.status,root.ln.wf01.wt01,BOOLEAN,PLAIN,\n" + "root.ln.wf01.wt01.temperature,root.ln.wf01.wt01,FLOAT,RLE,\n", "root.ln.wf01.wt01.status,root.ln.wf01.wt01,BOOLEAN,PLAIN,\n" + "root.ln.wf01.wt01.temperature,root.ln.wf01.wt01,FLOAT,RLE,\n", "", "" };
        for (int n = 0; n < sqls.length; n++) {
            String sql = sqls[n];
            String standard = standards[n];
            StringBuilder builder = new StringBuilder();
            try {
                boolean hasResultSet = statement.execute(sql);
                if (hasResultSet) {
                    ResultSet resultSet = statement.getResultSet();
                    ResultSetMetaData resultSetMetaData = resultSet.getMetaData();
                    while (resultSet.next()) {
                        for (int i = 1; i <= resultSetMetaData.getColumnCount(); i++) {
                            builder.append(resultSet.getString(i)).append(",");
                        }
                        builder.append("\n");
                    }
                }
                Assert.assertEquals(builder.toString(), standard);
            } catch (SQLException e) {
                e.printStackTrace();
                fail(e.getMessage());
            }
        }
        statement.close();
    } finally {
        connection.close();
    }
}

